(()=>{'use strict';if(window.DEMO_PAGE?.id!=='BL-02-03')return;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],key='blacklake-demo-v30-bom-overrides';
const fields={'产品名称':{column:'产品名称',link:'product',required:true,extraColumns:['产品ID','产品编号','产品规格','产品属性']},'投料工序':{column:'投料工序',link:'process',extraColumns:['投料工序ID']},'计划缺料状态':{column:'计划缺料状态',status:true},'计划缺料数量':{column:'计划缺料数'},'库存缺料状态':{column:'库存缺料状态',status:true},'库存缺料数量':{column:'库存缺料数'},'净需求数':{column:'净需求数'},'供应商(可编辑)':{column:'供应商(可编辑)',link:'vendor',extraColumns:['供应商ID(可编辑)']}};
let openedContext=null,storedAtOpen=null,undoContext=null;let state={},undo=null,bar=null,normal=null,popup=null,choices=null,field='计划缺料数量',selection=[],back=null;try{const raw=JSON.parse(localStorage.getItem(key)||'{}');if(raw&&typeof raw.values==='object'&&!Array.isArray(raw.values)){state=raw.values;undo=typeof raw.undo==='string'?raw.undo:null;undoContext=raw.undoContext||null;}}catch{}
window.DEMO_V30_BOM_FIELDS=(detail,node)=>{const scope=window.ENHANCED_BOM_SCOPE?.(detail)||detail;const v=state[scope]?.[node];if(!v||typeof v!=='object')return{};return Object.fromEntries([...new Set(Object.values(fields).flatMap(x=>[x.column,...x.extraColumns||[]]))].filter(c=>Object.hasOwn(v,c)).map(c=>[c,v[c]]));};
const selected=()=>$$('[data-v28-bom-node]').filter(r=>$('input[type=checkbox]',r)?.checked);
function update(){const rows=selected();if(!normal)normal=$('.kodo-art-table-toolbar:not([data-v30-toolbar])');if(!normal)return;if(!bar){const box=document.createElement('div');box.innerHTML=window.REVIEWED_V30_BULK_ASSETS.toolbar;bar=box.firstElementChild;bar.dataset.v30Toolbar='';normal.before(bar);$$('button',bar).forEach(b=>{const name=b.textContent.trim();b.dataset.v30Action=name;if(!['修改','导出','撤销多选'].includes(name)){b.disabled=true;b.title='恢复路径或业务接口尚未验收';}});const b=document.createElement('button');b.className='kodo-new-btn';b.textContent='撤销本地修改';b.dataset.v30Action='undo';$('.kodo-art-table-toolbar-right',bar)?.prepend(b);}
bar.hidden=!rows.length;bar.style.display=rows.length?'':'none';normal.style.display=rows.length?'none':'';const text=$$('*',bar).find(e=>e.childElementCount===0&&/^4$/.test(e.textContent.trim()));if(text)text.dataset.v30Count='';const n=$('[data-v30-count]',bar);if(n)n.textContent=String(rows.length);$('[data-v30-action=undo]',bar).hidden=!undo;$('.demo-v3-selection-summary')?.remove();}
function close(){window.DEMO_V31_LINKS?.close();choices?.remove();choices=null;popup?.remove();popup=null;back?.focus();}
function input(){return $('.kodo-new-form-item:last-of-type input',popup);}
function setField(name){field=name;const live=$('.kodo-new-select>[aria-live]',popup);if(live)live.textContent=name;const label=$('.kodo-new-select-selection-item',popup);if(label){label.textContent=name;label.title=name;}const forms=$$('.kodo-new-form-item',popup),content=$('.kodo-new-form-item-control-input-content',forms[2]);$('.kodo-new-form-item-required',forms[2])?.classList.toggle('kodo-new-form-item-required',!fields[name]?.link||!!fields[name]?.required);const thirdLabel=$('label',forms[2]);thirdLabel?.classList.toggle('kodo-new-form-item-required',!fields[name]?.link||!!fields[name]?.required);if(fields[name]?.link){content.innerHTML=window.REVIEWED_V31_ASSETS.linkControl;const control=$('.kodo-new-select',content);control.dataset.v31Linked=fields[name].link;if(fields[name].link==='vendor'){const ph=document.createElement('span');ph.className='kodo-new-select-selection-placeholder';ph.textContent='请选择';$('.kodo-new-select-selection-wrap',control).append(ph);}$('input',control).setAttribute('aria-required',String(!!fields[name].required));}else if(fields[name]?.status){content.innerHTML='<select data-v30-value aria-label="修改为" class="kodo-new-input"><option value="">请选择</option><option>缺料</option><option>不缺料</option></select>';}else{content.innerHTML=window.REVIEWED_V30_BULK_ASSETS.valueInput;const value=$('input',content);value.setAttribute('aria-label','修改为');value.setAttribute('inputmode','decimal');value.value='';}$('.v30-validation',popup)?.remove();}
function open(){openedContext=window.ENHANCED_BOM_CONTEXT?.()||null;if(openedContext?.invalid){window.DEMO_CONTEXT.toast('增强版本上下文无效，未修改');return;}storedAtOpen=localStorage.getItem(key);selection=selected().map(r=>({detail:window.ENHANCED_BOM_SCOPE?.(r.dataset.v28Detail)||r.dataset.v28Detail,node:r.dataset.v28BomNode}));if(!selection.length||selection.length>500)return;back=$('[data-v30-action="修改"]');popup=document.createElement('div');popup.dataset.v30Modal='';popup.innerHTML='<div class="kodo-new-modal-mask"></div><div class="kodo-new-modal-wrap">'+window.REVIEWED_V30_BULK_ASSETS.quantity+'</div>';document.body.append(popup);const d=$('[role=dialog]',popup);d.style.transformOrigin='';d.setAttribute('aria-label','批量修改');setField('产品名称');$$('.kodo-new-select-focused',popup).forEach(e=>e.classList.remove('kodo-new-select-focused'));$('[aria-label=Close]',popup)?.focus();}
function error(text){let e=$('.v30-validation',popup);if(!e){e=document.createElement('div');e.className='v30-validation';e.setAttribute('role','alert');$('.kodo-new-modal-body',popup).append(e);}e.textContent=text;}
function commit(){if(JSON.stringify(openedContext)!==JSON.stringify(window.ENHANCED_BOM_CONTEXT?.()||null)||localStorage.getItem(key)!==storedAtOpen){error('BOM版本、修订或批量值已变化，请取消后重新打开');return;}const current=selected().map(r=>({detail:window.ENHANCED_BOM_SCOPE?.(r.dataset.v28Detail)||r.dataset.v28Detail,node:r.dataset.v28BomNode}));if(JSON.stringify(current)!==JSON.stringify(selection)){error('选择范围已变化，请取消后重新选择');return;}const spec=fields[field];if(!spec){error('此字段关联选择器尚未接通');return;}const input=$('[aria-label="修改为"]',popup),value=input.value;const amount=Number(value);let updates;if(spec.link){const id=input.dataset.v31Entity||'',choice=window.DEMO_V31_LINKS.resolve(spec.link,id);if((id&&!choice)||(spec.required&&!choice)){error('请选择有效的本地关联记录');return;}updates=spec.link==='product'?{'产品名称':choice.name,'产品ID':choice.id,'产品编号':choice.code,'产品规格':choice.spec,'产品属性':choice.type}:spec.link==='process'?{'投料工序':choice?.name||'—','投料工序ID':choice?.id||'未提供'}:{'供应商(可编辑)':choice?.name||'—','供应商ID(可编辑)':choice?.id||'未提供'};}else{if(!value.trim()||(!spec.status&&(!Number.isFinite(amount)||amount<0))){error(spec.status?'请选择缺料状态':'请输入大于或等于0的有限数字');return;}updates={[spec.column]:spec.status?value:amount};}const before=JSON.stringify(state),next=JSON.parse(before);for(const s of selection){next[s.detail]??={};next[s.detail][s.node]??={};Object.assign(next[s.detail][s.node],updates);}try{localStorage.setItem(key,JSON.stringify({values:next,undo:before,undoContext:openedContext}));}catch{error('本地存储不可用，未修改任何行');return;}undo=before;undoContext=openedContext;state=next;close();window.dispatchEvent(new Event('v30-bom-render'));update();window.DEMO_CONTEXT.toast('已修改所选本地演示行；可重新选择后撤销本地修改');}
function clear(){const checks=$$('.kodo-art-table input[type=checkbox]');checks.forEach(e=>{e.checked=false;e.indeterminate=false;e.closest('.kodo-new-checkbox')?.classList.remove('kodo-new-checkbox-checked','kodo-new-checkbox-indeterminate');e.closest('.kodo-art-table-row')?.classList.remove('kodo-art-table-row-selected');});update();}
function exportRows(){const rows=selected(),headers=$$('.kodo-art-table-thead .kodo-art-table-row>.kodo-art-table-cell').map(e=>e.textContent.trim());const cols=['明细ID','BOM节点ID',...new Set(Object.values(fields).flatMap(x=>[x.column,...x.extraColumns||[]]))];const data=rows.map(r=>{const values=window.DEMO_V30_BOM_FIELDS(r.dataset.v28Detail,r.dataset.v28BomNode);return[r.dataset.v28Detail,r.dataset.v28BomNode,...cols.slice(2).map(c=>values[c]??r.children[headers.indexOf(c)]?.textContent.trim()??'未提供')];});if(!window.DEMO_V31_XLSX){window.DEMO_CONTEXT.toast('XLSX组件未加载，未导出');return;}const numeric=new Set(['计划缺料数','库存缺料数','净需求数']);const typed=data.map(row=>row.map((value,i)=>numeric.has(cols[i])&&value!==''&&value!=='未提供'&&Number.isFinite(Number(value))?Number(value):value));window.DEMO_V31_XLSX(cols,typed);window.DEMO_CONTEXT.toast('已导出所选本地演示行（.xlsx）');}

window.addEventListener('click',e=>{if(popup?.contains(e.target)){const linked=e.target.closest('[data-v31-linked]');if(linked){e.preventDefault();e.stopImmediatePropagation();window.DEMO_V31_LINKS.open(linked,linked.dataset.v31Linked);return;}const step=e.target.closest('.kodo-new-input-number-handler');if(step){e.preventDefault();e.stopImmediatePropagation();const value=$('[aria-label="修改为"]',popup),now=Number(value.value)||0;value.value=String(Math.max(0,now+(step.classList.contains('kodo-new-input-number-handler-up')?1:-1)));value.dispatchEvent(new Event('input',{bubbles:true}));return;}const b=e.target.closest('button'),name=b?.textContent.replace(/\s/g,'');if(b&&(b.getAttribute('aria-label')==='Close'||name==='取消')){e.preventDefault();e.stopImmediatePropagation();close();return;}if(name==='确定修改'){e.preventDefault();e.stopImmediatePropagation();commit();return;}if(e.target.closest('.kodo-new-form-item')===$$('.kodo-new-form-item',popup)[0]){e.preventDefault();e.stopImmediatePropagation();choices?.remove();choices=document.createElement('div');choices.className='v30-field-menu';choices.setAttribute('role','listbox');for(const name of Object.keys(fields)){const b=document.createElement('button');b.type='button';b.setAttribute('role','option');b.textContent=name;b.dataset.v30Field=name;choices.append(b);}const rect=$('.kodo-new-select',popup).getBoundingClientRect();choices.style.left=rect.left+'px';choices.style.top=rect.bottom+4+'px';choices.style.width=rect.width+'px';document.body.append(choices);return;}if(e.target.closest('input,select,label'))e.stopImmediatePropagation();return;}
const option=e.target.closest('[data-v30-field]');if(option){e.preventDefault();e.stopImmediatePropagation();setField(option.dataset.v30Field);choices.remove();choices=null;return;}const b=e.target.closest('[data-v30-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(['安排采购','生成采购需求','智能补货','齐套计算','删除'].includes(b.dataset.v30Action)&&window.ENHANCED_WORKBENCH_OPEN){window.ENHANCED_WORKBENCH_OPEN(b.dataset.v30Action);return;}switch(b.dataset.v30Action){case'修改':open();break;case'撤销多选':clear();break;case'导出':window.DEMO_V31_LINKS.openExport(b,exportRows);break;case'undo':if(!undoContext||JSON.stringify(undoContext)!==JSON.stringify(window.ENHANCED_BOM_CONTEXT?.()||null)){window.DEMO_CONTEXT.toast('撤销绑定的BOM版本或修订已变化，未执行');return;}try{localStorage.setItem(key,JSON.stringify({values:JSON.parse(undo),undo:null,undoContext:null}));}catch{window.DEMO_CONTEXT.toast('本地存储不可用，未执行撤销');return;}state=JSON.parse(undo);undo=null;undoContext=null;window.dispatchEvent(new Event('v30-bom-render'));update();window.DEMO_CONTEXT.toast('已恢复本次本地修改前的值');break;}},true);
window.addEventListener('keydown',e=>{if(popup?.contains(e.target)&&e.target.matches('input[aria-label="修改为"]')&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const now=Number(e.target.value)||0;e.target.value=String(Math.max(0,now+(e.key==='ArrowUp'?1:-1)));e.target.setAttribute('aria-valuenow',e.target.value);return;}if(e.key==='Escape'&&(popup||choices)){e.preventDefault();e.stopImmediatePropagation();if(choices){choices.remove();choices=null;}else close();}},true);
window.addEventListener('storage',e=>{if(e.key!==key)return;try{const raw=JSON.parse(e.newValue||'{}');state=raw.values||{};undo=raw.undo||null;undoContext=raw.undoContext||null;window.dispatchEvent(new Event('v30-bom-render'));update();}catch{}});
window.addEventListener('change',e=>{if(e.target.matches('.kodo-art-table input[type=checkbox]'))update();});
window.addEventListener('DOMContentLoaded',()=>{const body=$('.kodo-art-table-tbody');if(body)new MutationObserver(update).observe(body,{childList:true});update();});
})();
